// Generated from public/ at deploy time. Served directly by the worker instead of an ASSETS binding.
export const STATIC_FILES = {
  "/api.js": { contentType: "application/javascript; charset=utf-8", text: "// Thin fetch wrapper for the worker's /api/* endpoints.\n\nclass ApiError extends Error {\n  constructor(message, code) {\n    super(message);\n    this.code = code;\n  }\n}\n\nasync function call(path, { method = 'GET', body } = {}) {\n  let res;\n  try {\n    res = await fetch(path, {\n      method,\n      headers: body !== undefined ? { 'Content-Type': 'application/json' } : undefined,\n      body: body !== undefined ? JSON.stringify(body) : undefined,\n      credentials: 'same-origin',\n    });\n  } catch (e) {\n    // offline / network down: writes must fail clearly, reads fall back to cached data elsewhere.\n    throw new ApiError('لا يوجد اتصال بالإنترنت حالياً', 'offline');\n  }\n  let data = null;\n  try { data = await res.json(); } catch (_) { /* no body */ }\n  if (!res.ok || (data && data.ok === false)) {\n    const code = (data && data.error) || String(res.status);\n    throw new ApiError(errorMessage(code, res.status), code);\n  }\n  return data;\n}\n\nfunction errorMessage(code, status) {\n  const map = {\n    auth: 'انتهت الجلسة، سجّل الدخول مرة ثانية',\n    forbidden: 'ما عندك صلاحية لهذا الإجراء',\n    locked: 'محاولات كثيرة فاشلة، حاول بعد شوي',\n    wrong: 'اسم الدخول أو كلمة المرور غير صحيحة',\n    conflict: 'تم تعديل هذه الصفقة من مكان ثاني، حدّث الصفحة',\n    not_configured: 'النظام غير مُهيّأ بعد',\n    already_set_up: 'تم إعداد النظام من قبل',\n    phone_taken: 'اسم الدخول مستخدم من قبل',\n    invalid: 'البيانات المدخلة غير صحيحة',\n    offline: 'لا يوجد اتصال بالإنترنت حالياً',\n  };\n  return map[code] || `حدث خطأ (${code || status})`;\n}\n\nexport const api = {\n  setup: (body) => call('/api/setup', { method: 'POST', body }),\n  login: (body) => call('/api/login', { method: 'POST', body }),\n  logout: () => call('/api/logout', { method: 'POST' }),\n  data: () => call('/api/data'),\n  saveDeal: (body) => call('/api/deal', { method: 'POST', body }),\n  addActivity: (body) => call('/api/activity', { method: 'POST', body }),\n  saveSettings: (body) => call('/api/settings', { method: 'POST', body }),\n  listUsers: () => call('/api/users'),\n  usersAction: (body) => call('/api/users', { method: 'POST', body }),\n  kitSnapshot: (fresh) => call(`/api/sources/kit${fresh ? '?fresh=1' : ''}`),\n  publerSnapshot: (fresh) => call(`/api/sources/publer${fresh ? '?fresh=1' : ''}`),\n};\n\nexport { ApiError };\n" },
  "/app.js": { contentType: "application/javascript; charset=utf-8", text: "import { api, ApiError } from './api.js';\nimport {\n  STAGES, LOST_REASONS, CALL_OUTCOMES, ACTIVITY_KINDS, ACTIVITY_KIND_NAMES, stageOf, stageIndex, BUSINESSES,\n} from './constants.js';\nimport { renderRep } from './views/rep.js';\nimport { renderManager } from './views/manager.js';\n\nconst root = document.getElementById('app');\n\nexport const App = {\n  state: null,\n  refreshData,\n  rerender: renderMain,\n  logout,\n  toast,\n  openDeal,\n  BUSINESSES,\n  STAGES,\n};\n\n// ---------- boot ----------\nif ('serviceWorker' in navigator) {\n  window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {}));\n}\n\nboot();\n\nasync function boot() {\n  try {\n    const data = await api.data();\n    App.state = data;\n    renderMain();\n  } catch (e) {\n    if (e instanceof ApiError && (e.code === 'auth' || e.code === '401')) renderLogin();\n    else renderLogin(e.message);\n  }\n}\n\nasync function refreshData() {\n  try {\n    const data = await api.data();\n    App.state = data;\n    renderMain();\n  } catch (e) {\n    if (e instanceof ApiError && e.code === 'auth') renderLogin();\n    else toast(e.message, true);\n  }\n}\n\nfunction renderMain() {\n  root.innerHTML = '';\n  if (App.state.user.role === 'manager') renderManager(root, App);\n  else renderRep(root, App);\n}\n\nasync function logout() {\n  try { await api.logout(); } catch (_) { /* ignore */ }\n  App.state = null;\n  renderLogin();\n}\n\n// ---------- login / one-time setup ----------\nfunction renderLogin(message) {\n  root.innerHTML = '';\n  const wrap = document.createElement('div');\n  wrap.className = 'login-wrap';\n  wrap.innerHTML = `\n    <div class=\"login-card\">\n      <h1>نظام المبيعات</h1>\n      <div class=\"sub\">نهر · أتمتها</div>\n      ${message ? `<div class=\"error-box\">${esc(message)}</div>` : ''}\n      <form id=\"login-form\">\n        <div class=\"field\">\n          <label>اسم الدخول</label>\n          <input name=\"phone\" type=\"text\" required autocomplete=\"username\" />\n        </div>\n        <div class=\"field\">\n          <label>كلمة المرور</label>\n          <input name=\"password\" type=\"password\" required autocomplete=\"current-password\" />\n        </div>\n        <button class=\"btn btn-primary btn-block\" type=\"submit\">دخول</button>\n      </form>\n      <div class=\"login-switch\">\n        <button type=\"button\" id=\"show-setup\">إعداد أول حساب مدير</button>\n      </div>\n      <form id=\"setup-form\" style=\"display:none; margin-top:14px; border-top:1px solid var(--border); padding-top:14px;\">\n        <div class=\"hint\" style=\"margin-bottom:10px;\">لمرة واحدة فقط: يُستخدم فيها كلمة مرور CRM_PASSWORD القديمة لإنشاء أول حساب مدير.</div>\n        <div class=\"field\"><label>كلمة المرور القديمة (CRM_PASSWORD)</label><input name=\"password\" type=\"password\" required /></div>\n        <div class=\"field\"><label>اسمك</label><input name=\"name\" required /></div>\n        <div class=\"field\"><label>اسم دخولك</label><input name=\"phone\" type=\"text\" required /></div>\n        <div class=\"field\"><label>كلمة مرور جديدة (8 أحرف فأكثر)</label><input name=\"newPassword\" type=\"password\" minlength=\"8\" required /></div>\n        <button class=\"btn btn-primary btn-block\" type=\"submit\">إنشاء الحساب</button>\n      </form>\n    </div>`;\n  root.appendChild(wrap);\n\n  wrap.querySelector('#show-setup').addEventListener('click', () => {\n    const f = wrap.querySelector('#setup-form');\n    f.style.display = f.style.display === 'none' ? 'block' : 'none';\n  });\n\n  wrap.querySelector('#login-form').addEventListener('submit', async (ev) => {\n    ev.preventDefault();\n    const fd = new FormData(ev.target);\n    const btn = ev.target.querySelector('button');\n    btn.disabled = true;\n    try {\n      await api.login({ phone: fd.get('phone'), password: fd.get('password') });\n      await boot();\n    } catch (e) {\n      renderLogin(e.message);\n    } finally {\n      btn.disabled = false;\n    }\n  });\n\n  wrap.querySelector('#setup-form').addEventListener('submit', async (ev) => {\n    ev.preventDefault();\n    const fd = new FormData(ev.target);\n    const btn = ev.target.querySelector('button');\n    btn.disabled = true;\n    try {\n      await api.setup({\n        password: fd.get('password'), name: fd.get('name'), phone: fd.get('phone'), newPassword: fd.get('newPassword'),\n      });\n      await boot();\n    } catch (e) {\n      renderLogin(e.message);\n    } finally {\n      btn.disabled = false;\n    }\n  });\n}\n\n// ---------- small shared helpers ----------\nexport function esc(s) {\n  return String(s == null ? '' : s).replace(/[&<>\"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n}\n\nexport function toast(message, isErr) {\n  document.querySelectorAll('.toast').forEach((t) => t.remove());\n  const t = document.createElement('div');\n  t.className = 'toast' + (isErr ? ' err' : '');\n  t.textContent = message;\n  document.body.appendChild(t);\n  setTimeout(() => t.remove(), 3200);\n}\n\nexport function fmtDate(iso) {\n  if (!iso) return '';\n  try { return new Date(iso).toLocaleDateString('ar-SA', { day: 'numeric', month: 'short' }); } catch (_) { return iso; }\n}\nexport function fmtDateTime(iso) {\n  if (!iso) return '';\n  try { return new Date(iso).toLocaleString('ar-SA', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }); } catch (_) { return iso; }\n}\nexport function todayStr() {\n  return new Date().toISOString().slice(0, 10);\n}\nexport function nextStepClass(dateStr) {\n  if (!dateStr) return '';\n  const today = todayStr();\n  if (dateStr < today) return 'overdue';\n  if (dateStr === today) return 'today';\n  return '';\n}\n\n// Finds the lead for a deal's leadId.\nexport function leadById(state, leadId) {\n  return state.leads.find((l) => l.id === leadId);\n}\n\n// Builds the list of (lead, business, deal) \"opportunities\" a user can work with.\n// Reps only ever get rows that already have a deal assigned to them (server-filtered);\n// managers additionally see lead x business combinations with no deal row yet, synthesized\n// from the lead's seed stage, so unassigned leads are visible and assignable.\nexport function listOpportunities(state) {\n  const isManager = state.user.role === 'manager';\n  const out = [];\n  const seen = new Set();\n  for (const d of state.deals) {\n    out.push({ lead: leadById(state, d.leadId), business: d.business, deal: d });\n    seen.add(`${d.leadId}|${d.business}`);\n  }\n  if (isManager) {\n    for (const l of state.leads) {\n      for (const b of l.businesses) {\n        const key = `${l.id}|${b}`;\n        if (seen.has(key)) continue;\n        const seed = (l.seed && l.seed[b]) || { stage: 'new', at: null };\n        const s = stageOf(b, seed.stage);\n        out.push({\n          lead: l, business: b,\n          deal: {\n            leadId: l.id, business: b, stage: s.id, maxIdx: Math.max(0, stageIndex(b, s.id)),\n            owner: '', ownerUserId: null, ownerName: null, value: null, nextStep: '', nextStepAt: '',\n            lostReason: '', updatedAt: null, isNew: true,\n          },\n        });\n      }\n    }\n  }\n  return out.filter((o) => o.lead);\n}\n\n// ---------- deal detail bottom sheet (shared by rep + manager views) ----------\nexport function openDeal(lead, business, deal) {\n  const isManager = App.state.user.role === 'manager';\n  const backdrop = document.createElement('div');\n  backdrop.className = 'sheet-backdrop';\n  backdrop.addEventListener('click', (e) => { if (e.target === backdrop) close(); });\n  document.body.appendChild(backdrop);\n  function close() { backdrop.remove(); }\n\n  function activitiesFor() {\n    return App.state.activities\n      .filter((a) => a.lead_id === lead.id && a.business === business)\n      .sort((a, b) => (a.at < b.at ? 1 : -1));\n  }\n\n  function paint() {\n    const stages = STAGES[business];\n    const s = stageOf(business, deal.stage);\n    const acts = activitiesFor();\n    const team = App.state.team || [];\n    backdrop.innerHTML = `\n      <div class=\"sheet\" role=\"dialog\" aria-modal=\"true\">\n        <div class=\"grabber\"></div>\n        <h2>${esc(lead.name || 'بدون اسم')}</h2>\n        <div class=\"sub\">\n          <span class=\"pill pill-${business}\">${esc(BUSINESSES[business].name)}</span>\n          ${lead.grade ? ` · ${esc(lead.grade)}` : ''}\n          ${lead.date ? ` · ${esc(lead.date)}` : ''}\n        </div>\n\n        <section>\n          <h3>التواصل</h3>\n          <div class=\"details-list\">\n            ${lead.phone ? `<div class=\"d-row\"><span class=\"k\">الجوال</span><a href=\"tel:${esc(lead.phone)}\">${esc(lead.phone)}</a> · <a href=\"https://wa.me/${esc(lead.phone.replace(/\\D/g, ''))}\" target=\"_blank\" rel=\"noopener\">واتساب</a></div>` : ''}\n            ${lead.email ? `<div class=\"d-row\"><span class=\"k\">الإيميل</span><a href=\"mailto:${esc(lead.email)}\">${esc(lead.email)}</a></div>` : ''}\n            ${lead.from ? `<div class=\"d-row\"><span class=\"k\">مصدره</span><span>${esc(lead.from)}</span></div>` : ''}\n          </div>\n        </section>\n\n        <section>\n          <h3>المرحلة</h3>\n          <div class=\"stage-grid\">\n            ${stages.map((st) => `<button class=\"btn btn-sm stage-btn ${st.id === s.id ? 'current' : ''} ${st.lost ? 'lost' : ''} ${st.won ? 'won' : ''}\" data-stage=\"${st.id}\">${esc(st.name)}</button>`).join('')}\n          </div>\n          <div id=\"lost-reason-wrap\" style=\"display:none; margin-top:10px;\">\n            <label>سبب الخسارة</label>\n            <div class=\"stage-grid\">${LOST_REASONS.map((r) => `<button type=\"button\" class=\"btn btn-sm\" data-reason=\"${esc(r)}\">${esc(r)}</button>`).join('')}</div>\n          </div>\n        </section>\n\n        ${isManager ? `\n        <section>\n          <h3>المسؤول</h3>\n          <select id=\"owner-select\">\n            <option value=\"\">غير معيّن</option>\n            ${team.map((t) => `<option value=\"${t.id}\" ${deal.ownerUserId === t.id ? 'selected' : ''} ${!t.active ? 'disabled' : ''}>${esc(t.name)}${!t.active ? ' (موقوف)' : ''}</option>`).join('')}\n          </select>\n        </section>` : ''}\n\n        <section>\n          <h3>القيمة المتوقعة (ر.س)</h3>\n          <div style=\"display:flex; gap:8px;\">\n            <input id=\"value-input\" type=\"number\" min=\"0\" step=\"1\" value=\"${deal.value ?? ''}\" placeholder=\"القيمة\" />\n            <button class=\"btn btn-sm\" id=\"save-value\">حفظ</button>\n          </div>\n        </section>\n\n        <section>\n          <h3>الخطوة القادمة</h3>\n          <div class=\"field\"><input id=\"next-step-text\" placeholder=\"مثال: اتصال متابعة\" value=\"${esc(deal.nextStep || '')}\" /></div>\n          <div style=\"display:flex; gap:8px;\">\n            <input id=\"next-step-date\" type=\"date\" value=\"${esc(deal.nextStepAt || '')}\" />\n            <button class=\"btn btn-sm\" id=\"save-next\">حفظ</button>\n          </div>\n        </section>\n\n        <section>\n          <h3>تسجيل نشاط</h3>\n          <div class=\"activity-grid\">\n            ${ACTIVITY_KINDS.map((k) => `<button type=\"button\" class=\"btn activity-btn\" data-kind=\"${k.id}\"><span class=\"ic\">${k.icon}</span><span>${esc(k.name)}</span></button>`).join('')}\n          </div>\n          <div id=\"activity-form\" style=\"display:none; margin-top:10px;\"></div>\n        </section>\n\n        <section>\n          <h3>السجل</h3>\n          <div class=\"activity-log\">\n            ${acts.length ? acts.map((a) => `\n              <div class=\"activity-item\">\n                <div>${describeActivity(a)}</div>\n                <div class=\"meta\">${esc(a.by)} · ${fmtDateTime(a.at)}</div>\n              </div>`).join('') : '<div class=\"hint\">ما فيه نشاط مسجل بعد.</div>'}\n          </div>\n        </section>\n\n        <button class=\"btn btn-ghost btn-block\" id=\"close-sheet\">إغلاق</button>\n      </div>`;\n\n    backdrop.querySelector('#close-sheet').addEventListener('click', close);\n\n    backdrop.querySelectorAll('.stage-btn').forEach((btn) => btn.addEventListener('click', () => {\n      const stageId = btn.dataset.stage;\n      const target = stages.find((x) => x.id === stageId);\n      if (target.lost) {\n        backdrop.querySelector('#lost-reason-wrap').style.display = 'block';\n        return;\n      }\n      doPatch({ stage: stageId });\n    }));\n    backdrop.querySelectorAll('[data-reason]').forEach((btn) => btn.addEventListener('click', () => {\n      doPatch({ stage: 'lost', lostReason: btn.dataset.reason });\n    }));\n\n    if (isManager) {\n      backdrop.querySelector('#owner-select').addEventListener('change', (e) => {\n        doPatch({ ownerUserId: e.target.value || null });\n      });\n    }\n\n    backdrop.querySelector('#save-value').addEventListener('click', () => {\n      const v = backdrop.querySelector('#value-input').value;\n      doPatch({ value: v === '' ? null : v });\n    });\n    backdrop.querySelector('#save-next').addEventListener('click', () => {\n      doPatch({ nextStep: backdrop.querySelector('#next-step-text').value, nextStepAt: backdrop.querySelector('#next-step-date').value });\n    });\n\n    backdrop.querySelectorAll('[data-kind]').forEach((btn) => btn.addEventListener('click', () => showActivityForm(btn.dataset.kind)));\n  }\n\n  function showActivityForm(kind) {\n    const wrap = backdrop.querySelector('#activity-form');\n    const needsOutcome = kind === 'call';\n    const needsText = kind === 'note';\n    wrap.style.display = 'block';\n    wrap.innerHTML = `\n      ${needsOutcome ? `<div class=\"stage-grid\" style=\"margin-bottom:8px;\">${CALL_OUTCOMES.map((o) => `<button type=\"button\" class=\"btn btn-sm\" data-outcome=\"${o.id}\">${esc(o.name)}</button>`).join('')}</div>` : ''}\n      <textarea id=\"activity-text\" placeholder=\"${needsText ? 'اكتب الملاحظة...' : 'تفاصيل إضافية (اختياري)'}\"></textarea>\n      <button class=\"btn btn-primary btn-sm\" style=\"margin-top:8px;\" id=\"send-activity\">تسجيل ${esc(ACTIVITY_KIND_NAMES[kind])}</button>`;\n    let outcome = '';\n    wrap.querySelectorAll('[data-outcome]').forEach((b) => b.addEventListener('click', () => {\n      outcome = b.dataset.outcome;\n      wrap.querySelectorAll('[data-outcome]').forEach((x) => x.classList.remove('current'));\n      b.classList.add('current');\n    }));\n    wrap.querySelector('#send-activity').addEventListener('click', async () => {\n      const text = wrap.querySelector('#activity-text').value.trim();\n      if (needsText && !text) { toast('اكتب الملاحظة أولاً', true); return; }\n      try {\n        await api.addActivity({ leadId: lead.id, business, kind, text, outcome });\n        await App.refreshData();\n        toast('تم التسجيل');\n        reopenFromState();\n      } catch (e) { toast(e.message, true); }\n    });\n  }\n\n  async function doPatch(patch) {\n    try {\n      await api.saveDeal({ leadId: lead.id, business, expect: deal.updatedAt || null, patch });\n      await App.refreshData();\n      toast('تم الحفظ');\n      reopenFromState();\n    } catch (e) {\n      if (e.code === 'conflict') { toast('تم تعديلها من مكان ثاني، أعِد المحاولة', true); await App.refreshData(); close(); }\n      else toast(e.message, true);\n    }\n  }\n\n  function reopenFromState() {\n    const fresh = App.state.deals.find((d) => d.leadId === lead.id && d.business === business);\n    if (fresh) { deal = fresh; paint(); } else close();\n  }\n\n  paint();\n}\n\nfunction describeActivity(a) {\n  const names = { stage: 'تغيير مرحلة', owner_assign: 'تعيين مسؤول', owner: 'تعديل المسؤول', value: 'تعديل القيمة', next_step: 'خطوة قادمة' };\n  if (a.kind in names) {\n    if (a.kind === 'stage') return `${names.stage}: ${esc(stageLabel(a.business, a.from_stage))} ← ${esc(stageLabel(a.business, a.to_stage))}${a.text ? ` (${esc(a.text)})` : ''}`;\n    return `${names[a.kind]}${a.text ? `: ${esc(a.text)}` : ''}`;\n  }\n  const kindName = ACTIVITY_KIND_NAMES[a.kind] || a.kind;\n  const outcomeName = CALL_OUTCOMES.find((o) => o.id === a.outcome);\n  return `${esc(kindName)}${outcomeName ? ` · ${esc(outcomeName.name)}` : ''}${a.text ? `: ${esc(a.text)}` : ''}`;\n}\nfunction stageLabel(business, stageId) {\n  if (!stageId) return '—';\n  return stageOf(business, stageId).name;\n}\n" },
  "/constants.js": { contentType: "application/javascript; charset=utf-8", text: "// Mirrors worker/src/shared.js. Duplicated on purpose: the frontend is plain static files with\n// no build step, so it can't import from the worker. Keep the two in sync if stages ever change.\n\nexport const BUSINESSES = {\n  nahr: { id: 'nahr', name: 'نهر' },\n  atmatha: { id: 'atmatha', name: 'أتمتها' },\n};\n\nexport const STAGES = {\n  nahr: [\n    { id: 'new', name: 'جديد' },\n    { id: 'contacted', name: 'تم التواصل' },\n    { id: 'call', name: 'مكالمة اكتشاف' },\n    { id: 'proposal', name: 'عرض سعر مرسل' },\n    { id: 'negotiation', name: 'تفاوض' },\n    { id: 'won', name: 'ربح', won: true },\n    { id: 'lost', name: 'خسارة', lost: true },\n  ],\n  atmatha: [\n    { id: 'new', name: 'جديد' },\n    { id: 'contacted', name: 'تم التواصل' },\n    { id: 'call', name: 'مكالمة محجوزة' },\n    { id: 'attended', name: 'حضر المكالمة' },\n    { id: 'won', name: 'اشترك', won: true },\n    { id: 'lost', name: 'ما اشترك', lost: true },\n  ],\n};\n\nexport const LOST_REASONS = ['السعر', 'التوقيت', 'ما رد', 'غير مناسب', 'اختار غيرنا', 'أخرى'];\nexport const CALL_OUTCOMES = [\n  { id: 'answered', name: 'رد' },\n  { id: 'no_answer', name: 'ما رد' },\n  { id: 'booked', name: 'حجز موعد' },\n];\nexport const ACTIVITY_KINDS = [\n  { id: 'call', name: 'اتصال', icon: '📞' },\n  { id: 'whatsapp', name: 'واتساب', icon: '💬' },\n  { id: 'note', name: 'ملاحظة', icon: '📝' },\n  { id: 'email', name: 'إيميل', icon: '✉️' },\n  { id: 'meeting', name: 'اجتماع', icon: '🤝' },\n];\nexport const ACTIVITY_KIND_NAMES = Object.fromEntries(ACTIVITY_KINDS.map((k) => [k.id, k.name]));\n\nexport function stageOf(business, stageId) {\n  return STAGES[business].find((s) => s.id === stageId) || STAGES[business][0];\n}\nexport function stageIndex(business, stageId) {\n  return STAGES[business].findIndex((s) => s.id === stageId);\n}\n" },
  "/index.html": { contentType: "text/html; charset=utf-8", text: "<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\" />\n    <meta name=\"robots\" content=\"noindex, nofollow\" />\n    <meta name=\"theme-color\" content=\"#050F24\" media=\"(prefers-color-scheme: light)\" />\n    <meta name=\"theme-color\" content=\"#050F24\" media=\"(prefers-color-scheme: dark)\" />\n    <meta name=\"mobile-web-app-capable\" content=\"yes\" />\n    <meta name=\"apple-mobile-web-app-capable\" content=\"yes\" />\n    <meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\" />\n    <meta name=\"apple-mobile-web-app-title\" content=\"نظام المبيعات\" />\n    <link rel=\"manifest\" href=\"/manifest.json\" />\n    <link rel=\"apple-touch-icon\" href=\"/icons/icon-192.png\" />\n    <link rel=\"icon\" href=\"/icons/icon-192.png\" />\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Alexandria:wght@500;600;700;800&family=IBM+Plex+Sans+Arabic:wght@400;500;600&display=swap\" />\n    <link rel=\"stylesheet\" href=\"/styles.css\" />\n    <title>نظام المبيعات · نهر وأتمتها</title>\n  </head>\n  <body>\n    <div id=\"app\"></div>\n    <script type=\"module\" src=\"/app.js\"></script>\n  </body>\n</html>\n" },
  "/manifest.json": { contentType: "application/json; charset=utf-8", text: "{\n  \"name\": \"نظام المبيعات · نهر وأتمتها\",\n  \"short_name\": \"المبيعات\",\n  \"description\": \"نظام إدارة المبيعات لمشروعي نهر وأتمتها\",\n  \"start_url\": \"/\",\n  \"scope\": \"/\",\n  \"display\": \"standalone\",\n  \"orientation\": \"portrait\",\n  \"background_color\": \"#050F24\",\n  \"theme_color\": \"#050F24\",\n  \"dir\": \"rtl\",\n  \"lang\": \"ar\",\n  \"icons\": [\n    { \"src\": \"/icons/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/icons/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"any\" },\n    { \"src\": \"/icons/icon-192.png\", \"sizes\": \"192x192\", \"type\": \"image/png\", \"purpose\": \"maskable\" },\n    { \"src\": \"/icons/icon-512.png\", \"sizes\": \"512x512\", \"type\": \"image/png\", \"purpose\": \"maskable\" }\n  ]\n}\n" },
  "/styles.css": { contentType: "text/css; charset=utf-8", text: "/* Palette lifted from the old app's bundled CSS (app.css): dark navy, one blue accent. */\n:root {\n  --bg: #050F24;\n  --panel: #0C1B3A;\n  --panel-2: #12244A;\n  --border: #1B2F58;\n  --border-soft: #33405A;\n  --text: #ECEFF3;\n  --text-dim: #C3CCDD;\n  --text-faint: #8D9AB5;\n  --accent: #00A4FE;\n  --accent-soft: #7FD0FF;\n  --accent-2: #8FD3FF;\n  --danger: #FF9C94;\n  --danger-strong: #C62828;\n  --ok: #3ddc84;\n  --radius: 14px;\n  --radius-lg: 20px;\n  --gutter: 16px;\n  --font-head: 'Alexandria', system-ui, sans-serif;\n  --font-body: 'IBM Plex Sans Arabic', system-ui, sans-serif;\n}\n\n* { box-sizing: border-box; }\nhtml, body { height: 100%; }\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--text);\n  font-family: var(--font-body);\n  -webkit-font-smoothing: antialiased;\n  overflow-x: hidden;\n}\nh1, h2, h3, h4, .brand { font-family: var(--font-head); }\nbutton, input, select, textarea { font-family: inherit; color: inherit; }\na { color: var(--accent-soft); }\n\n#app { min-height: 100%; display: flex; flex-direction: column; }\n\n/* ---------- generic layout ---------- */\n.topbar {\n  position: sticky; top: 0; z-index: 20;\n  display: flex; align-items: center; gap: 10px;\n  padding: 12px var(--gutter);\n  padding-top: calc(12px + env(safe-area-inset-top));\n  background: rgba(5, 15, 36, 0.92);\n  backdrop-filter: blur(6px);\n  border-bottom: 1px solid var(--border);\n}\n.topbar .brand { font-weight: 700; font-size: 17px; }\n.topbar .spacer { flex: 1; }\n.topbar .who { font-size: 13px; color: var(--text-dim); }\n\n.page { flex: 1; padding: var(--gutter); padding-bottom: calc(90px + env(safe-area-inset-bottom)); max-width: 820px; margin: 0 auto; width: 100%; }\n\n.tabs { display: flex; gap: 6px; overflow-x: auto; padding: 2px; margin-bottom: 14px; -ms-overflow-style: none; scrollbar-width: none; }\n.tabs::-webkit-scrollbar { display: none; }\n.tab-btn {\n  flex: none;\n  padding: 9px 16px;\n  border-radius: 999px;\n  border: 1px solid var(--border);\n  background: var(--panel);\n  color: var(--text-dim);\n  font-size: 14px;\n  white-space: nowrap;\n}\n.tab-btn.active { background: var(--accent); border-color: var(--accent); color: #04121f; font-weight: 600; }\n\n.bottom-nav {\n  position: fixed; inset-inline: 0; bottom: 0; z-index: 20;\n  display: flex;\n  padding: 6px var(--gutter) calc(6px + env(safe-area-inset-bottom));\n  background: rgba(5, 15, 36, 0.96);\n  border-top: 1px solid var(--border);\n  backdrop-filter: blur(6px);\n}\n.bottom-nav button {\n  flex: 1;\n  background: none; border: none;\n  color: var(--text-faint);\n  font-size: 12px;\n  padding: 8px 4px;\n  border-radius: 10px;\n  display: flex; flex-direction: column; align-items: center; gap: 2px;\n}\n.bottom-nav button .ic { font-size: 19px; }\n.bottom-nav button.active { color: var(--accent-soft); background: var(--panel-2); }\n\n/* ---------- buttons/forms ---------- */\nbutton { cursor: pointer; }\n.btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 6px;\n  border-radius: 12px; border: 1px solid var(--border-soft);\n  background: var(--panel-2); color: var(--text);\n  padding: 11px 16px; font-size: 15px; min-height: 44px;\n}\n.btn:active { transform: scale(0.98); }\n.btn-primary { background: var(--accent); border-color: var(--accent); color: #04121f; font-weight: 700; }\n.btn-danger { background: rgba(255, 156, 148, 0.12); border-color: var(--danger); color: var(--danger); }\n.btn-ghost { background: transparent; border-color: transparent; color: var(--text-dim); }\n.btn-sm { padding: 7px 12px; font-size: 13px; min-height: 36px; border-radius: 10px; }\n.btn-block { width: 100%; }\n.btn[disabled] { opacity: 0.5; pointer-events: none; }\n\nlabel { display: block; font-size: 13px; color: var(--text-dim); margin: 0 0 6px; }\ninput, select, textarea {\n  width: 100%;\n  background: var(--panel);\n  border: 1px solid var(--border-soft);\n  border-radius: 10px;\n  padding: 11px 12px;\n  font-size: 15px;\n  outline: none;\n}\ninput:focus, select:focus, textarea:focus { border-color: var(--accent); }\n.field { margin-bottom: 14px; }\ntextarea { resize: vertical; min-height: 70px; }\n\n.pill { display: inline-flex; align-items: center; gap: 4px; padding: 3px 10px; border-radius: 999px; font-size: 12px; border: 1px solid var(--border-soft); color: var(--text-dim); }\n.pill-nahr { border-color: var(--accent); color: var(--accent-soft); }\n.pill-atmatha { border-color: #c38fff; color: #d9b8ff; }\n.pill-won { border-color: var(--ok); color: var(--ok); }\n.pill-lost { border-color: var(--danger); color: var(--danger); }\n\n.error-box { background: rgba(255, 156, 148, 0.12); border: 1px solid var(--danger); color: var(--danger); border-radius: 10px; padding: 10px 12px; font-size: 14px; margin-bottom: 14px; }\n.hint { font-size: 12px; color: var(--text-faint); margin-top: 4px; }\n.empty-state { text-align: center; color: var(--text-faint); padding: 50px 20px; font-size: 14px; }\n\n/* ---------- login ---------- */\n.login-wrap { min-height: 100%; display: flex; align-items: center; justify-content: center; padding: var(--gutter); }\n.login-card { width: 100%; max-width: 380px; background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 26px 22px; }\n.login-card h1 { font-size: 20px; margin: 0 0 4px; text-align: center; }\n.login-card .sub { text-align: center; color: var(--text-faint); font-size: 13px; margin-bottom: 20px; }\n.login-switch { text-align: center; margin-top: 14px; font-size: 13px; }\n.login-switch button { background: none; border: none; color: var(--accent-soft); font-size: 13px; }\n\n/* ---------- cards ---------- */\n.card-list { display: flex; flex-direction: column; gap: 10px; }\n.deal-card {\n  background: var(--panel);\n  border: 1px solid var(--border);\n  border-radius: var(--radius);\n  padding: 14px;\n  text-align: start;\n  width: 100%;\n  display: flex; flex-direction: column; gap: 8px;\n}\n.deal-card:active { background: var(--panel-2); }\n.deal-card .row1 { display: flex; justify-content: space-between; align-items: center; gap: 8px; }\n.deal-card .name { font-size: 16px; font-weight: 700; }\n.deal-card .value { font-size: 14px; color: var(--accent-soft); font-weight: 600; white-space: nowrap; }\n.deal-card .row2 { display: flex; justify-content: space-between; align-items: center; gap: 8px; }\n.deal-card .next { font-size: 13px; color: var(--text-dim); }\n.deal-card .next.overdue { color: var(--danger); font-weight: 600; }\n.deal-card .next.today { color: var(--accent-soft); font-weight: 600; }\n\n/* ---------- bottom sheet ---------- */\n.sheet-backdrop {\n  position: fixed; inset: 0; background: rgba(0, 0, 0, 0.55); z-index: 40;\n  display: flex; align-items: flex-end;\n}\n.sheet {\n  width: 100%; max-height: 92vh; overflow-y: auto;\n  background: var(--panel); border-radius: 20px 20px 0 0;\n  border-top: 1px solid var(--border);\n  padding: 10px var(--gutter) calc(20px + env(safe-area-inset-bottom));\n  animation: sheet-up 0.18s ease-out;\n}\n@keyframes sheet-up { from { transform: translateY(16px); opacity: 0.6; } to { transform: translateY(0); opacity: 1; } }\n.sheet .grabber { width: 40px; height: 4px; border-radius: 4px; background: var(--border-soft); margin: 4px auto 14px; }\n.sheet h2 { font-size: 18px; margin: 0 0 2px; }\n.sheet .sub { font-size: 13px; color: var(--text-faint); margin-bottom: 14px; }\n.sheet section { margin-bottom: 18px; }\n.sheet section > h3 { font-size: 13px; color: var(--text-faint); font-weight: 600; margin: 0 0 8px; }\n\n.stage-grid { display: flex; flex-wrap: wrap; gap: 8px; }\n.stage-btn { flex: none; }\n.stage-btn.current { background: var(--accent); border-color: var(--accent); color: #04121f; font-weight: 700; }\n.stage-btn.lost { border-color: var(--danger); color: var(--danger); }\n.stage-btn.won { border-color: var(--ok); color: var(--ok); }\n\n.activity-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(64px, 1fr)); gap: 8px; }\n.activity-btn { display: flex; flex-direction: column; align-items: center; gap: 4px; padding: 10px 4px; font-size: 12px; }\n.activity-btn .ic { font-size: 20px; }\n\n.activity-log { display: flex; flex-direction: column; gap: 8px; max-height: 240px; overflow-y: auto; }\n.activity-item { font-size: 13px; color: var(--text-dim); padding-bottom: 8px; border-bottom: 1px dashed var(--border); }\n.activity-item .meta { color: var(--text-faint); font-size: 11px; }\n\n.details-list { display: flex; flex-direction: column; gap: 6px; font-size: 13px; }\n.details-list .d-row { display: flex; gap: 8px; }\n.details-list .d-row .k { color: var(--text-faint); flex: none; min-width: 110px; }\n\n/* ---------- manager-only pieces ---------- */\n.filters-row { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }\n.filters-row select { width: auto; }\n\n.table-wrap { overflow-x: auto; }\ntable.plain { width: 100%; border-collapse: collapse; font-size: 14px; }\ntable.plain th, table.plain td { text-align: start; padding: 10px 8px; border-bottom: 1px solid var(--border); white-space: nowrap; }\ntable.plain th { color: var(--text-faint); font-weight: 600; font-size: 12px; }\n\n.kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; margin-bottom: 16px; }\n.kpi { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); padding: 12px; }\n.kpi .n { font-size: 20px; font-weight: 700; }\n.kpi .l { font-size: 12px; color: var(--text-faint); }\n\n.section-card { background: var(--panel); border: 1px solid var(--border); border-radius: var(--radius); padding: 14px; margin-bottom: 14px; }\n.section-card h3 { margin: 0 0 12px; font-size: 15px; }\n.row-between { display: flex; justify-content: space-between; align-items: center; gap: 10px; }\n\n.toast {\n  position: fixed; bottom: calc(80px + env(safe-area-inset-bottom)); left: 50%; transform: translateX(-50%);\n  background: var(--panel-2); border: 1px solid var(--border-soft); color: var(--text);\n  padding: 10px 16px; border-radius: 10px; font-size: 13px; z-index: 60; max-width: 90vw; text-align: center;\n}\n.toast.err { border-color: var(--danger); color: var(--danger); }\n\n@media (min-width: 720px) {\n  .card-list { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }\n}\n" },
  "/sw.js": { contentType: "application/javascript; charset=utf-8", text: "// App-shell cache only. No offline write queue on purpose (out of scope) -- writes just fail\n// clearly with \"no connection\" when offline (see api.js). This only makes the shell load fast\n// and tolerates brief offline moments for re-reading data already fetched this session.\nconst CACHE = 'crm-shell-v1';\nconst SHELL = [\n  '/', '/index.html', '/styles.css', '/app.js', '/api.js', '/constants.js',\n  '/views/rep.js', '/views/manager.js', '/manifest.json',\n  '/icons/icon-192.png', '/icons/icon-512.png',\n];\n\nself.addEventListener('install', (event) => {\n  event.waitUntil(\n    caches.open(CACHE).then((cache) => cache.addAll(SHELL)).then(() => self.skipWaiting()),\n  );\n});\n\nself.addEventListener('activate', (event) => {\n  event.waitUntil(\n    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()),\n  );\n});\n\nself.addEventListener('fetch', (event) => {\n  const { request } = event;\n  if (request.method !== 'GET') return; // never cache/intercept writes\n  const url = new URL(request.url);\n  if (url.pathname.startsWith('/api/')) return; // always go to the network for data\n\n  // App shell: cache-first, falling back to network, so launch is instant and brief offline\n  // moments don't block showing the UI the person already loaded.\n  event.respondWith(\n    caches.match(request).then((cached) => {\n      const network = fetch(request)\n        .then((res) => {\n          if (res && res.ok) caches.open(CACHE).then((cache) => cache.put(request, res.clone()));\n          return res;\n        })\n        .catch(() => cached);\n      return cached || network;\n    }),\n  );\n});\n" },
  "/views/manager.js": { contentType: "application/javascript; charset=utf-8", text: "import { api } from '../api.js';\nimport { BUSINESSES, STAGES, stageOf } from '../constants.js';\nimport {\n  esc, toast, fmtDate, nextStepClass, listOpportunities, openDeal,\n} from '../app.js';\n\nlet activeTab = 'pipeline';\nlet filters = { business: 'all', rep: 'all' };\n\nexport function renderManager(root, App) {\n  const state = App.state;\n  const wrap = document.createElement('div');\n  wrap.innerHTML = `\n    <div class=\"topbar\">\n      <div class=\"brand\">لوحة المدير</div>\n      <div class=\"spacer\"></div>\n      <div class=\"who\">${esc(state.user.name)}</div>\n      <button class=\"btn btn-ghost btn-sm\" id=\"logout-btn\">خروج</button>\n    </div>\n    <div class=\"page\" id=\"tab-content\"></div>\n    <div class=\"bottom-nav\">\n      ${navBtn('pipeline', '📋', 'الصفقات')}\n      ${navBtn('team', '👥', 'الفريق')}\n      ${navBtn('settings', '⚙️', 'الإعدادات')}\n      ${navBtn('sources', '📡', 'المصادر')}\n    </div>`;\n  root.appendChild(wrap);\n  wrap.querySelector('#logout-btn').addEventListener('click', () => App.logout());\n  wrap.querySelectorAll('.bottom-nav button').forEach((b) => b.addEventListener('click', () => {\n    activeTab = b.dataset.tab;\n    renderManager(resetRoot(root), App);\n  }));\n\n  const content = wrap.querySelector('#tab-content');\n  if (activeTab === 'pipeline') paintPipeline(content, App);\n  else if (activeTab === 'team') paintTeam(content, App);\n  else if (activeTab === 'settings') paintSettings(content, App);\n  else paintSources(content, App);\n}\n\nfunction navBtn(tab, icon, label) {\n  return `<button data-tab=\"${tab}\" class=\"${activeTab === tab ? 'active' : ''}\"><span class=\"ic\">${icon}</span><span>${label}</span></button>`;\n}\nfunction resetRoot(root) { root.innerHTML = ''; return root; }\n\n// ---------- pipeline ----------\nfunction paintPipeline(content, App) {\n  const state = App.state;\n  const team = state.team || [];\n  content.innerHTML = `\n    <div class=\"filters-row\">\n      <select id=\"f-biz\">\n        <option value=\"all\">كل الأنشطة</option>\n        <option value=\"nahr\">نهر</option>\n        <option value=\"atmatha\">أتمتها</option>\n      </select>\n      <select id=\"f-rep\">\n        <option value=\"all\">كل الفريق</option>\n        <option value=\"unassigned\">غير معيّن</option>\n        ${team.map((t) => `<option value=\"${t.id}\">${esc(t.name)}</option>`).join('')}\n      </select>\n    </div>\n    <div id=\"pipeline-body\"></div>`;\n  content.querySelector('#f-biz').value = filters.business;\n  content.querySelector('#f-rep').value = filters.rep;\n  content.querySelector('#f-biz').addEventListener('change', (e) => { filters.business = e.target.value; paintPipeline(content, App); });\n  content.querySelector('#f-rep').addEventListener('change', (e) => { filters.rep = e.target.value; paintPipeline(content, App); });\n\n  let opps = listOpportunities(state);\n  if (filters.business !== 'all') opps = opps.filter((o) => o.business === filters.business);\n  if (filters.rep === 'unassigned') opps = opps.filter((o) => !o.deal.ownerUserId);\n  else if (filters.rep !== 'all') opps = opps.filter((o) => o.deal.ownerUserId === filters.rep);\n\n  const body = content.querySelector('#pipeline-body');\n  if (!opps.length) { body.innerHTML = '<div class=\"empty-state\">ما فيه صفقات مطابقة.</div>'; return; }\n\n  // grouped by business then stage, like a simple vertical kanban\n  const businesses = filters.business === 'all' ? ['nahr', 'atmatha'] : [filters.business];\n  let html = '';\n  for (const biz of businesses) {\n    const rows = opps.filter((o) => o.business === biz);\n    if (!rows.length) continue;\n    html += `<h3 style=\"margin: 18px 0 8px;\">${esc(BUSINESSES[biz].name)} <span class=\"hint\">(${rows.length})</span></h3>`;\n    for (const stage of STAGES[biz]) {\n      const inStage = rows.filter((o) => o.deal.stage === stage.id);\n      if (!inStage.length) continue;\n      html += `<div class=\"hint\" style=\"margin:10px 0 6px;\">${esc(stage.name)} · ${inStage.length}</div>`;\n      html += `<div class=\"card-list\">${inStage.map((o, i) => cardHtml(o)).join('')}</div>`;\n    }\n  }\n  body.innerHTML = html;\n  body.querySelectorAll('.deal-card').forEach((card) => {\n    const leadId = card.dataset.leadId, biz = card.dataset.biz;\n    card.addEventListener('click', () => {\n      const o = opps.find((x) => x.lead.id === leadId && x.business === biz);\n      openDeal(o.lead, o.business, o.deal);\n    });\n  });\n}\n\nfunction cardHtml({ lead, business, deal }) {\n  const s = stageOf(business, deal.stage);\n  const cls = nextStepClass(deal.nextStepAt);\n  const ownerLabel = deal.ownerName || 'غير معيّن';\n  return `\n    <button type=\"button\" class=\"deal-card\" data-lead-id=\"${esc(lead.id)}\" data-biz=\"${esc(business)}\">\n      <div class=\"row1\">\n        <span class=\"name\">${esc(lead.name || 'بدون اسم')}</span>\n        ${deal.value ? `<span class=\"value\">${Number(deal.value).toLocaleString('ar-SA')} ر.س</span>` : ''}\n      </div>\n      <div class=\"row2\">\n        <span class=\"pill ${s.won ? 'pill-won' : s.lost ? 'pill-lost' : ''}\">${esc(s.name)}</span>\n        <span class=\"hint\">${esc(ownerLabel)}</span>\n      </div>\n      <div class=\"next ${cls}\">${deal.nextStepAt ? fmtDate(deal.nextStepAt) : 'بدون خطوة قادمة'}</div>\n    </button>`;\n}\n\n// ---------- team ----------\nfunction paintTeam(content, App) {\n  const state = App.state;\n  const team = state.team || [];\n  const counts = team.map((t) => {\n    const mine = state.deals.filter((d) => d.ownerUserId === t.id);\n    const open = mine.filter((d) => !stageOf(d.business, d.stage).won && !stageOf(d.business, d.stage).lost).length;\n    const won = mine.filter((d) => stageOf(d.business, d.stage).won).length;\n    return { ...t, total: mine.length, open, won };\n  });\n  content.innerHTML = `\n    <div class=\"section-card\">\n      <h3>الفريق</h3>\n      <div class=\"table-wrap\">\n        <table class=\"plain\">\n          <thead><tr><th>الاسم</th><th>مفتوحة</th><th>مربوحة</th><th>الحالة</th><th></th></tr></thead>\n          <tbody>\n            ${counts.map((t) => `\n              <tr>\n                <td>${esc(t.name)}</td>\n                <td>${t.open}</td>\n                <td>${t.won}</td>\n                <td>${t.active ? 'نشط' : 'موقوف'}</td>\n                <td style=\"display:flex; gap:6px;\">\n                  <button class=\"btn btn-sm\" data-act=\"reset\" data-id=\"${t.id}\">كلمة مرور جديدة</button>\n                  <button class=\"btn btn-sm ${t.active ? 'btn-danger' : ''}\" data-act=\"${t.active ? 'deactivate' : 'activate'}\" data-id=\"${t.id}\">${t.active ? 'إيقاف' : 'تفعيل'}</button>\n                </td>\n              </tr>`).join('') || '<tr><td colspan=\"5\" class=\"hint\">ما فيه مندوبين بعد</td></tr>'}\n          </tbody>\n        </table>\n      </div>\n    </div>\n\n    <div class=\"section-card\">\n      <h3>إضافة مندوب</h3>\n      <form id=\"add-rep-form\">\n        <div class=\"field\"><label>الاسم</label><input name=\"name\" required /></div>\n        <div class=\"field\"><label>اسم الدخول</label><input name=\"phone\" type=\"text\" required /></div>\n        <div class=\"field\"><label>كلمة مرور مبدئية (8 أحرف فأكثر)</label><input name=\"password\" type=\"password\" minlength=\"8\" required /></div>\n        <button class=\"btn btn-primary btn-block\" type=\"submit\">إضافة</button>\n      </form>\n    </div>`;\n\n  content.querySelectorAll('[data-act]').forEach((btn) => btn.addEventListener('click', async () => {\n    const id = btn.dataset.id, act = btn.dataset.act;\n    try {\n      if (act === 'reset') {\n        const pw = prompt('كلمة المرور الجديدة (8 أحرف فأكثر):');\n        if (!pw) return;\n        await api.usersAction({ action: 'reset_password', id, password: pw });\n        toast('تم تغيير كلمة المرور');\n      } else {\n        await api.usersAction({ action: act, id });\n        toast(act === 'deactivate' ? 'تم إيقاف الحساب' : 'تم تفعيل الحساب');\n        await App.refreshData();\n        App.rerender();\n      }\n    } catch (e) { toast(e.message, true); }\n  }));\n\n  content.querySelector('#add-rep-form').addEventListener('submit', async (ev) => {\n    ev.preventDefault();\n    const fd = new FormData(ev.target);\n    try {\n      await api.usersAction({ action: 'create', name: fd.get('name'), phone: fd.get('phone'), password: fd.get('password') });\n      toast('تمت الإضافة');\n      ev.target.reset();\n      await App.refreshData();\n      paintTeam(content, App);\n    } catch (e) { toast(e.message, true); }\n  });\n}\n\n// ---------- settings ----------\nfunction paintSettings(content, App) {\n  const state = App.state;\n  const dv = (state.settings && state.settings.defaultValue) || {};\n  content.innerHTML = `\n    <div class=\"section-card\">\n      <h3>القيمة الافتراضية للصفقة (ر.س)</h3>\n      <form id=\"settings-form\">\n        <div class=\"field\"><label>نهر</label><input name=\"nahr\" type=\"number\" min=\"0\" value=\"${dv.nahr ?? ''}\" /></div>\n        <div class=\"field\"><label>أتمتها</label><input name=\"atmatha\" type=\"number\" min=\"0\" value=\"${dv.atmatha ?? ''}\" /></div>\n        <button class=\"btn btn-primary btn-block\" type=\"submit\">حفظ</button>\n      </form>\n    </div>`;\n  content.querySelector('#settings-form').addEventListener('submit', async (ev) => {\n    ev.preventDefault();\n    const fd = new FormData(ev.target);\n    try {\n      await api.saveSettings({ defaultValue: { nahr: fd.get('nahr'), atmatha: fd.get('atmatha') } });\n      toast('تم الحفظ');\n      await App.refreshData();\n    } catch (e) { toast(e.message, true); }\n  });\n}\n\n// ---------- sources (Kit / Publer snapshots) ----------\nfunction paintSources(content, App) {\n  const state = App.state;\n  content.innerHTML = `\n    <div class=\"section-card\">\n      <div class=\"row-between\"><h3>Kit (النشرة البريدية)</h3><button class=\"btn btn-sm\" id=\"kit-refresh\">تحديث</button></div>\n      <div id=\"kit-body\" class=\"hint\">${state.sources.kit ? 'اضغط تحديث لعرض البيانات' : 'غير مفعّل (لا يوجد KIT_API_KEY)'}</div>\n    </div>\n    <div class=\"section-card\">\n      <div class=\"row-between\"><h3>Publer (النشر على السوشال)</h3><button class=\"btn btn-sm\" id=\"publer-refresh\">تحديث</button></div>\n      <div id=\"publer-body\" class=\"hint\">${state.sources.publer ? 'اضغط تحديث لعرض البيانات' : 'غير مفعّل (لا يوجد PUBLER_API_KEY)'}</div>\n    </div>`;\n\n  content.querySelector('#kit-refresh').addEventListener('click', async () => {\n    const body = content.querySelector('#kit-body');\n    body.textContent = 'جارٍ التحميل...';\n    try {\n      const d = await api.kitSnapshot();\n      if (!d.connected) { body.textContent = 'غير مفعّل'; return; }\n      if (d.error) { body.textContent = 'تعذّر الجلب الآن'; return; }\n      body.innerHTML = `\n        <div class=\"kpi-grid\">\n          <div class=\"kpi\"><div class=\"n\">${d.allTime ?? '—'}</div><div class=\"l\">إجمالي المشتركين</div></div>\n          <div class=\"kpi\"><div class=\"n\">${d.recentTotal ?? '—'}</div><div class=\"l\">آخر 120 يوم</div></div>\n          <div class=\"kpi\"><div class=\"n\">${(d.broadcasts || []).length}</div><div class=\"l\">آخر الرسائل</div></div>\n        </div>\n        <div class=\"table-wrap\"><table class=\"plain\"><thead><tr><th>العنوان</th><th>التاريخ</th><th>فتح</th><th>نقر</th></tr></thead><tbody>\n          ${(d.broadcasts || []).slice(0, 10).map((b) => `<tr><td>${esc(b.subject)}</td><td>${fmtDate(b.sentAt)}</td><td>${b.openRate ?? '—'}</td><td>${b.clickRate ?? '—'}</td></tr>`).join('')}\n        </tbody></table></div>`;\n    } catch (e) { body.textContent = e.message; }\n  });\n\n  content.querySelector('#publer-refresh').addEventListener('click', async () => {\n    const body = content.querySelector('#publer-body');\n    body.textContent = 'جارٍ التحميل...';\n    try {\n      const d = await api.publerSnapshot();\n      if (!d.connected) { body.textContent = 'غير مفعّل'; return; }\n      if (d.error) { body.textContent = 'تعذّر الجلب الآن'; return; }\n      body.innerHTML = `<div class=\"table-wrap\"><table class=\"plain\"><thead><tr><th>الشبكة</th><th>النص</th><th>التاريخ</th></tr></thead><tbody>\n        ${(d.posts || []).slice(0, 15).map((p) => `<tr><td>${esc(p.network)}</td><td>${esc(p.text)}</td><td>${fmtDate(p.at)}</td></tr>`).join('')}\n      </tbody></table></div>`;\n    } catch (e) { body.textContent = e.message; }\n  });\n}\n" },
  "/views/rep.js": { contentType: "application/javascript; charset=utf-8", text: "import { BUSINESSES, stageOf } from '../constants.js';\nimport {\n  esc, fmtDate, nextStepClass, listOpportunities, openDeal,\n} from '../app.js';\n\nlet filterBusiness = 'all';\n\nexport function renderRep(root, App) {\n  const state = App.state;\n  const wrap = document.createElement('div');\n  wrap.innerHTML = `\n    <div class=\"topbar\">\n      <div class=\"brand\">صفقاتي</div>\n      <div class=\"spacer\"></div>\n      <div class=\"who\">${esc(state.user.name)}</div>\n      <button class=\"btn btn-ghost btn-sm\" id=\"logout-btn\">خروج</button>\n    </div>\n    <div class=\"page\">\n      <div class=\"tabs\" id=\"biz-tabs\">\n        <button class=\"tab-btn ${filterBusiness === 'all' ? 'active' : ''}\" data-biz=\"all\">الكل</button>\n        <button class=\"tab-btn ${filterBusiness === 'nahr' ? 'active' : ''}\" data-biz=\"nahr\">نهر</button>\n        <button class=\"tab-btn ${filterBusiness === 'atmatha' ? 'active' : ''}\" data-biz=\"atmatha\">أتمتها</button>\n      </div>\n      <div id=\"card-list\" class=\"card-list\"></div>\n    </div>`;\n  root.appendChild(wrap);\n\n  wrap.querySelector('#logout-btn').addEventListener('click', () => App.logout());\n  wrap.querySelectorAll('#biz-tabs .tab-btn').forEach((b) => b.addEventListener('click', () => {\n    filterBusiness = b.dataset.biz;\n    renderRep(resetRoot(root), App);\n  }));\n\n  paintList(wrap, App);\n}\n\nfunction resetRoot(root) {\n  root.innerHTML = '';\n  return root;\n}\n\nfunction paintList(wrap, App) {\n  const state = App.state;\n  let opps = listOpportunities(state);\n  if (filterBusiness !== 'all') opps = opps.filter((o) => o.business === filterBusiness);\n\n  // Open deals first (soonest next step first, then no next step), closed deals last.\n  opps.sort((a, b) => {\n    const sa = stageOf(a.business, a.deal.stage), sb = stageOf(b.business, b.deal.stage);\n    const closedA = sa.won || sa.lost, closedB = sb.won || sb.lost;\n    if (closedA !== closedB) return closedA ? 1 : -1;\n    const da = a.deal.nextStepAt || '9999-99-99';\n    const db = b.deal.nextStepAt || '9999-99-99';\n    return da < db ? -1 : da > db ? 1 : 0;\n  });\n\n  const list = wrap.querySelector('#card-list');\n  if (!opps.length) {\n    list.innerHTML = '<div class=\"empty-state\">ما عندك صفقات بعد. إذا انتظرت شوي، راح يعيّن لك المدير عملاء.</div>';\n    return;\n  }\n  list.innerHTML = opps.map((o) => cardHtml(o)).join('');\n  list.querySelectorAll('.deal-card').forEach((card, i) => {\n    card.addEventListener('click', () => openDeal(opps[i].lead, opps[i].business, opps[i].deal));\n  });\n}\n\nfunction cardHtml({ lead, business, deal }) {\n  const s = stageOf(business, deal.stage);\n  const cls = nextStepClass(deal.nextStepAt);\n  const nextLabel = deal.nextStepAt\n    ? `${cls === 'overdue' ? 'متأخرة: ' : ''}${fmtDate(deal.nextStepAt)}${deal.nextStep ? ` · ${esc(deal.nextStep)}` : ''}`\n    : 'ما فيه خطوة قادمة محددة';\n  return `\n    <button type=\"button\" class=\"deal-card\">\n      <div class=\"row1\">\n        <span class=\"name\">${esc(lead.name || 'بدون اسم')}</span>\n        ${deal.value ? `<span class=\"value\">${Number(deal.value).toLocaleString('ar-SA')} ر.س</span>` : ''}\n      </div>\n      <div class=\"row2\">\n        <span class=\"pill pill-${business}\">${esc(BUSINESSES[business].name)}</span>\n        <span class=\"pill ${s.won ? 'pill-won' : s.lost ? 'pill-lost' : ''}\">${esc(s.name)}</span>\n      </div>\n      <div class=\"next ${cls}\">${nextLabel}</div>\n    </button>`;\n}\n" },
  "/icons/icon-192.png": { contentType: "image/png", b64: "" },
  "/icons/icon-512.png": { contentType: "image/png", b64: "" },
};
